### API Integration

**LeanIX GraphQL Query Example:**

```graphql
query TechnologyStackExport {
    allFactSheets(
        factSheetType: Application
        filter: { facetFilters: [{ facetKey: "category", keys: ["technology"] }] }
    ) {
        edges {
            node {
                id
                displayName
                category
                lifecycle {
                    phase
                }
                tags {
                    name
                }
                ... on Technology {
                    version
                    vendor
                    approvalStatus
                }
                relToApplication {
                    edges {
                        node {
                            factSheet {
                                id
                                displayName
                            }
                        }
                    }
                }
            }
        }
    }
}
```

